// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Drive the entry as the (default/uninitialized) depositor account so
        // the access-control require passes and the call succeeds on both versions.
        address depositor = c.depositorAccount();
        vm.prank(depositor);
        bool ok;
        try c.setL1BlockValues(
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY admissible input, a successful setL1BlockValues
        // call must never mutate c's state — in particular c.hash() keeps its
        // initial value bytes32(0). The mutant writes _hash, so for the fuzzed
        // _hash != bytes32(0) it violates the rule.
        assertTrue(!ok || c.hash() == bytes32(0));
    }
}
